starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

starter.variables.tf:
variable "image_name" {
  description = "Input variable image_name."
  type        = string
  default     = "nginx:alpine"
}

starter.main.tf:
provider "docker" {
  host = var.docker_host
}

